><form method="post" action="/admin/blood-components/specifications/toggle"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="blood_component_id" value="<?=(int)$bloodComponent['id']?>"><input type="hidden" name="specification_id" value="<?=(int)$sp['id']?>"><button class="table-action"><?=$sp['active']?'Inativar':'Ativar'?></button></form></div></td></tr><?php endforeach;?><?php if(!$specifications):?><tr><td colspan="8" class="empty">Nenhuma especificação configurada.</td></tr><?php endif;?></tbody></table></div>
<details class="specification-editor" data-spec-editor><summary class="button">+ Adicionar especificação</summary><form class="admin-form specification-form" method="post" action="/admin/blood-components/specifications/save"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="blood_component_id" value="<?=(int)$bloodComponent['id']?>"><input type="hidden" name="specification_id"><div class="spec-form-heading"><div><h3 data-spec-title>Nova especificação</h3><p>Escolha a regra e a condição; somente os campos necessários serão exibidos.</p></div></div><div class="form-grid specification-grid"><label class="spec-test"><span>Teste *</span><select name="test_id" required><option value="">Selecione</option><?php foreach($componentTests as $t):?><option value="<?=(int)$t['id']?>" data-unit="<?=htmlspecialchars($t['unit']??'')?>"><?=htmlspecialchars($t['name'])?></option><?php endforeach;?></select></label><label class="spec-rule"><span>Regra *</span><select name="rule_type"><?php foreach($ruleLabels as $code=>$label):?><option value="<?=$code?>"><?=htmlspecialchars($label)?></option><?php endforeach;?></select><small class="field-help" data-rule-help></small></label><label data-min-field><span data-min-label>Valor de referência</span><input inputmode="decimal" name="min_value"></label><label data-max-field hidden><span>Valor máximo</span><input inputmode="decimal" name="max_value"></label><label data-text-field hidden><span>Texto esperado</span><input name="expected_text" placeholder="Ex.: Negativa"></label><label data-boolean-field hidden><span>Resultado esperado</span><select data-boolean-select><option value="Sim">Sim</option><option value="Não">Não</option></select></label><label class="spec-unit"><span>Unidade</span><input name="unit"></label><label class="spec-condition"><span>Condição</span><select name="condition_type"><option value="">Sem condição — regra geral</option><?php foreach($conditionLabels as $code=>$label):?>