l" name="double_min_platelets" required value="<?= htmlspecialchars((string)($currentYieldRule['double_min_platelets']??'600000000000')) ?>"><small class="field-help">Inicial: 6,0 × 10¹¹</small></label><label><span>Status</span><select name="active"><option value="1" <?= ($currentYieldRule['active']??1)?'selected':'' ?>>Ativa</option><option value="0" <?= isset($currentYieldRule)&&!$currentYieldRule['active']?'selected':'' ?>>Inativa</option></select></label><label><span>Vigência inicial</span><input type="date" name="effective_from" value="<?= htmlspecialchars((string)($currentYieldRule['effective_from']??$today)) ?>"></label><label><span>Vigência final</span><input type="date" name="effective_to" value="<?= htmlspecialchars((string)($currentYieldRule['effective_to']??'')) ?>"></label><label><span>Fonte</span><input name="source_name" value="<?= htmlspecialchars((string)($currentYieldRule['source_name']??'Portaria GM/MS aplicável / regulamentação hemoterápica vigente')) ?>"></label><label><span>Referência</span><input name="source_reference" value="<?= htmlspecialchars((string)($currentYieldRule['source_reference']??'Classificação de CPAF por rendimento de Plaquetas/U')) ?>"></label><label class="component-description"><span>Notas</span><textarea name="notes" rows="2"><?= htmlspecialchars((string)($currentYieldRule['notes']??'')) ?></textarea></label></div><div class="form-actions"><button class="button">Salvar regra versionada</button></div></form></section><?php endif;?>
