<script>
(()=>{const details=document.querySelector('[data-spec-editor]');if(!details)return;const form=details.querySelector('form'),rule=form.elements.rule_type,condition=form.elements.condition_type,minField=form.querySelector('[data-min-field]'),maxField=form.querySelector('[data-max-field]'),textField=form.querySelector('[data-text-field]'),booleanField=form.querySelector('[data-boolean-field]'),expected=form.elements.expected_text,booleanSelect=form.querySelector('[data-boolean-select]'),conditionText=form.querySelector('[data-condition-text]'),preservative=form.querySelector('[data-preservative-field]'),fixed=form.querySelector('[data-fixed-condition]'),helps={GT:'O resultado deve ser superior ao valor informado.',GTE:'O resultado deve ser igual ou superior ao valor informado.',LT:'O resultado deve ser inferior ao valor informado.',LTE:'O resultado deve ser igual ou inferior ao valor informado.',BETWEEN:'O resultado deve permanecer dentro da faixa mínima e máxima.',EQUAL_NUMERIC:'O resultado deve ser igual ao valor informado.',EQUAL_TEXT:'O resultado deve corresponder ao texto informado.',BOOLEAN:'O resultado esperado é uma condição binária.'};
function rules(){const r=rule.value,numeric=['GT','GTE','LT','LTE','EQUAL_NUMERIC'].includes(r);minField.hidden=!numeric&&r!=='BETWEEN';maxField.hidden=r!=='BETWEEN';textField.hidden=r!=='EQUAL_TEXT';booleanField.hidden=r!=='BOOLEAN';form.querySelector('[data-min-label]').textContent=r==='BETWEEN'?'Valor mínimo':'Valor de referência';form.querySelector('[data-rule-help]').textContent=helps[r]||'';form.elements.min_value.required=numeric||r==='BETWEEN';form.elements.max_value.required=r==='BETWEEN';expected.required=r==='EQUAL_TEXT';if(r==='BOOLEAN')expected.value=booleanSelect.value;}
function conditions(){const c=condition.value,p=c==='PRESERVATIVE',typed=['PROCESS_METHOD','POOL_TYPE'].includes(c),storage=c==='STORAGE_DAY',binary=['LEUKOREDUCED','PATHOGEN_REDUCTION','PRE_STORAGE_LEUKOREDUCTION'].includes(c);preservative.hidden=!p;conditionText.hidden=!typed;fixed.hidden=!(storage||binary);form.elements.preservative_id.required=p;form.elements.condition_value.required=typed;form.querySelector('[data-condition-label]').textContent=c==='POOL_TYPE'?'Tipo de pool':'Método aplicável';form.querySelector('[data-fixed-condition-value]').value=storage?'Último dia de armazenamento':binary?'Sim':'';}
rule.addEventListener('change',rules);condition.addEventListener('change',conditions);booleanSelect.addEventListener('change',()=>expected.value=booleanSelect.value);form.elements.test_id.addEventListener('change',e=>{if(!form.elements.unit.value)form.elements.unit.value=e.target.selectedOptions[0]?.dataset.unit||''});
document.querySelectorAll('[data-edit-spec]').forEach(button=>button.addEventListener('click',()=>{const data=JSON.parse(button.closest('tr').dataset.specification);form.reset();Object.entries(data).forEach(([key,value])=>{if(form.elements[key]&&value!==null)form.elements[key].value=value});if(['LT','LTE'].includes(data.rule_type))form.elements.min_value.value=data.max_value||'';if(data.rule_type==='BOOLEAN')booleanSelect.value=data.expected_text||'Sim';form.querySelector('[data-spec-title]').textContent='Editar especificação — versão '+(data.version_number||1);form.querySelector('[data-save-spec]').textContent='Salvar alteração';details.open=true;rules();conditions();details.scrollIntoView({behavior:'smooth',block:'start'});}));
form.querySelector('[data-cancel-spec]').addEventListener('click',()=>{form.reset();form.elements.specification_id.value='';form.querySelector('[data-spec-title]').textContent='Nova especificação';form.querySelector('[data-save-spec]').textContent='Salvar especificação';details.open=false;rules();conditions();});
const modal=document.createElement('div');modal.className='qc-modal-backdrop';modal.hidden=true;modal.innerHTML='<div class="qc-modal" role="dialog" aria-modal="true"><h2>Salvar alteração</h2><p>Se esta especificação já tiver sido usada, o BloodHub criará uma nova versão e preservará todos os resultados anteriores.</p><div><button class="button button-secondary" type="button" data-back>Voltar</button><button class="button" type="button" data-confirm>Continuar</button></div></div>';document.body.appendChild(modal);let confirmed=false;form.addEventListener('submit',e=>{if(rule.value==='BOOLEAN')expected.value=booleanSelect.value;if(form.elements.specification_id.value&&!confirmed){e.preventDefault();modal.hidden=false;}});modal.querySelector('[data-back]').onclick=()=>modal.hidden=true;modal.querySelector('[data-confirm]').onclick=()=>{confirmed=true;modal.hidden=true;form.requestSubmit()};rules();conditions();})();
</script>
<script>
(()=>{
const rows=document.querySelectorAll('.specification-table tbody tr[data-specification]');if(!rows.length)return;
const usedModal=document.createElement('div');usedModal.className='qc-modal-backdrop';usedModal.hidden=true;usedModal.innerHTML='<div class="qc-modal" role="dialog" aria-modal="true"><h2>Especificação protegida</h2><p>Esta especificação já foi utilizada em resultados de controle de qualidade e não pode ser alterada. Crie uma nova especificação/versionamento para modificar os critérios.</p><div><button class="button" type="button" data-used-close>Entendi</button></div></div>';document.body.appendChild(usedModal);usedModal.querySelector('[data-used-close]').addEventListener('click',()=>usedModal.hidden=true);usedModal.addEventListener('click',event=>{if(event.target===usedModal)usedModal.hidden=true;});
const modal=document.createElement('div');modal.className='qc-modal-backdrop';modal.hidden=true;modal.innerHTML=`<div class="qc-modal specification-delete-modal" role="dialog" aria-modal="true" aria-labelledby="spec-delete-title"><h2 id="spec-delete-title">Excluir especificação?</h2><p>Esta especificação ainda não foi utilizada em nenhum resultado de controle de qualidade. A exclusão será definitiva.</p><dl class="spec-delete-summary"><div><dt>Teste</dt><dd data-delete-test></dd></div><div><dt>Regra</dt><dd data-delete-rule></dd></div><div><dt>Valor</dt><dd data-delete-value></dd></div><div><dt>Componente</dt><dd data-delete-component></dd></div></dl><div><button class="button button-secondary" type="button" data-delete-cancel>Cancelar</button><form method="post" action="/admin/blood-components/specifications/delete"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="blood_component_id" value="<?=(int)$bloodComponent['id']?>"><input type="hidden" name="specification_id"><button class="button button-danger" type="submit">Excluir definitivamente</button></form></div></div>`;document.body.appendChild(modal);modal.querySelector('[data-delete-component]').textContent=<?=json_encode((string)$bloodComponent['name'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
const ruleLabels=<?=json_encode($ruleLabels,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
const displayValue=data=>data.rule_type==='BETWEEN'?`${data.min_value} – ${data.max_value}`:(data.expected_text??data.min_value??data.max_value??'—');
rows.forEach(row=>{const data=JSON.parse(row.dataset.specification),actions=row.querySelector('.spec-actions'),edit=actions.querySelector('[data-edit-spec]');if(Number(data.is_used)){const replacement=edit.cloneNode(true);replacement.removeAttribute('data-edit-spec');replacement.title='Especificação já utilizada — edição não permitida.';replacement.addEventListener('click',()=>usedModal.hidden=false);edit.replaceWith(replacement);return;}const button=document.createElement('button');button.type='button';button.className='table-action table-action-danger';button.textContent='Excluir';button.addEventListener('click',()=>{modal.querySelector('[data-delete-test]').textContent=data.test_name;modal.querySelector('[data-delete-rule]').textContent=ruleLabels[data.rule_type]||data.rule_type;modal.querySelector('[data-delete-value]').textContent=displayValue(data);modal.querySelector('[name="specification_id"]').value=data.id;modal.hidden=false;});actions.appendChild(button);});
modal.querySelector('[data-delete-cancel]').addEventListener('click',()=>modal.hidden=true);modal.addEventListener('click',event=>{if(event.target===modal)modal.hidden=true;});
const saveModal=[...document.querySelectorAll('.qc-modal')].find(item=>item.querySelector('h2')?.textContent==='Salvar alteração');if(saveModal)saveModal.querySelector('p').textContent='Esta especificação ainda não foi utilizada. A alteração será salva no mesmo cadastro, preservando seu ID.';
})();
</script>
<script>
(()=>{const section=document.querySelector('[data-cpaf-version-config]');if(!section)return;const editor=section.querySelector('[data-cpaf-editor]'),form=editor.querySelector('form'),title=form.querySelector('[data-cpaf-title]'),save=form.querySelector('[data-save-cpaf]'),guidance=form.querySelector('[data-cpaf-guidance]'),modal=document.querySelector('[data-cpaf-modal]'),toggleForm=modal.querySelector('form');
const reset=()=>{form.reset();form.elements.rule_id.value='';form.elements.simple_min_platelets.value='300000000000';form.elements.double_min_platelets.value='600000000000';form.elements.effective_from.value='<?= $today ?>';title.textContent='Nova versão';save.textContent='Salvar nova versão';guidance.textContent='Defina os critérios que serão aplicados às novas classificações.';editor.open=false;};
section.querySelectorAll('[data-edit-cpaf]').forEach(button=>button.addEventListener('click',()=>{const data=JSON.parse(button.closest('tr').dataset.cpafRule);if(Number(data.is_used)){let notice=section.querySelector('[data-cpaf-used-notice]');if(!notice){notice=document.createElement('div');notice.className='alert alert-error cpaf-used-notice';notice.dataset.cpafUsedNotice='';section.querySelector('.section-heading').after(notice);}notice.textContent='Esta versão já foi utilizada em resultados e não pode ser editada. Crie uma nova versão para alterar os critérios de classificação.';notice.scrollIntoView({behavior:'smooth',block:'center'});return;}form.reset();Object.entries(data).forEach(([key,value])=>{if(form.elements[key]&&value!==null)form.elements[key].value=value});form.elements.simple_min_platelets.value=data.simple_input;form.elements.double_min_platelets.value=data.double_input;form.elements.rule_id.value=data.id;title.textContent='Editar versão v'+data.version_number;save.textContent='Salvar alterações';guidance.textContent='Esta versão ainda não foi utilizada; a edição manterá o mesmo ID e número.';editor.open=true;editor.scrollIntoView({behavior:'smooth',block:'start'});}));
form.querySelector('[data-cancel-cpaf]').addEventListener('click',reset);
section.querySelectorAll('[data-toggle-cpaf]').forEach(button=>button.addEventListener('click',()=>{const data=JSON.parse(button.closest('tr').dataset.cpafRule),activate=button.dataset.active==='1';toggleForm.elements.rule_id.value=data.id;toggleForm.elements.active.value=activate?'1':'0';modal.querySelector('[data-cpaf-modal-title]').textContent=(activate?'Ativar':'Inativar')+' versão v'+data.version_number+'?';modal.querySelector('[data-cpaf-modal-text]').textContent=activate?'A versão atualmente ativa será inativada automaticamente.':'Novas análises deixarão de utilizar esta regra. Resultados históricos permanecerão inalterados.';modal.querySelector('[data-cpaf-modal-confirm]').textContent=activate?'Ativar versão':'Inativar versão';modal.querySelector('[data-cpaf-modal-confirm]').classList.toggle('button-danger',!activate);modal.hidden=false;}));
modal.querySelector('[data-cpaf-modal-cancel]').addEventListener('click',()=>modal.hidden=true);modal.addEventListener('click',event=>{if(event.target===modal)modal.hidden=true});})();
</script>
